// Neon Runner – simple canvas game
// Canvas element with id="game" must exist in the page.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) { console.error('Canvas with id "game" not found'); return; }
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth || 800;
  const height = canvas.height = canvas.offsetHeight || 400;

  // Game constants
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const PLAYER_SIZE = 30;
  const SCROLL_SPEED = 4;
  const OBSTACLE_FREQ = 120; // frames
  const ORB_FREQ = 80;

  let frame = 0;
  let score = 0;
  let running = true;

  const player = {
    x: 80,
    y: height - PLAYER_SIZE,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    onGround: true,
    draw() {
      ctx.fillStyle = '#0ff'; // neon cyan
      ctx.fillRect(this.x, this.y, this.width, this.height);
    },
    update() {
      this.vy += GRAVITY;
      this.y += this.vy;
      if (this.y + this.height >= height) {
        this.y = height - this.height;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
    jump() {
      if (this.onGround) {
        this.vy = JUMP_VELOCITY;
        this.onGround = false;
      }
    }
  };

  const obstacles = [];
  const orbs = [];

  function spawnObstacle() {
    const size = 30 + Math.random() * 20;
    obstacles.push({
      x: width,
      y: height - size,
      width: size,
      height: size,
      draw() { ctx.fillStyle = '#f0f'; ctx.fillRect(this.x, this.y, this.width, this.height); },
    });
  }

  function spawnOrb() {
    const radius = 8;
    const yPos = height - PLAYER_SIZE - 80 - Math.random() * 120;
    orbs.push({
      x: width,
      y: yPos,
      r: radius,
      draw() { ctx.fillStyle = '#ff0'; ctx.beginPath(); ctx.arc(this.x, this.y, this.r, 0, Math.PI*2); ctx.fill(); },
    });
  }

  function rectCollide(a, b) {
    return a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
  }
  function circleRectCollide(circle, rect) {
    const distX = Math.abs(circle.x - rect.x - rect.width/2);
    const distY = Math.abs(circle.y - rect.y - rect.height/2);
    if (distX > (rect.width/2 + circle.r)) return false;
    if (distY > (rect.height/2 + circle.r)) return false;
    if (distX <= (rect.width/2)) return true;
    if (distY <= (rect.height/2)) return true;
    const dx = distX - rect.width/2;
    const dy = distY - rect.height/2;
    return (dx*dx + dy*dy <= (circle.r * circle.r));
  }

  function update() {
    frame++;
    // spawn
    if (frame % OBSTACLE_FREQ === 0) spawnObstacle();
    if (frame % ORB_FREQ === 0) spawnOrb();

    // move obstacles & check collisions
    for (let i = obstacles.length-1; i>=0; i--) {
      const o = obstacles[i];
      o.x -= SCROLL_SPEED;
      if (rectCollide(player, o)) running = false;
      if (o.x + o.width < 0) obstacles.splice(i,1);
    }
    for (let i = orbs.length-1; i>=0; i--) {
      const orb = orbs[i];
      orb.x -= SCROLL_SPEED;
      if (circleRectCollide(orb, player)) {
        score++;
        orbs.splice(i,1);
      } else if (orb.x + orb.r < 0) {
        orbs.splice(i,1);
      }
    }
    player.update();
  }

  function draw() {
    ctx.clearRect(0,0,width,height);
    // background
    ctx.fillStyle = '#111';
    ctx.fillRect(0,0,width,height);
    // ground line
    ctx.strokeStyle = '#555';
    ctx.beginPath(); ctx.moveTo(0,height-2); ctx.lineTo(width,height-2); ctx.stroke();
    // entities
    player.draw();
    obstacles.forEach(o=>o.draw());
    orbs.forEach(o=>o.draw());
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText('Score: '+score, 10,30);
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,width,height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.font = '40px sans-serif';
      ctx.fillText('Game Over', width/2, height/2);
    }
  }

  function loop(){
    if (running) {
      update();
    }
    draw();
    requestAnimationFrame(loop);
  }

  // input
  window.addEventListener('keydown', e=>{ if(e.code==='Space') player.jump(); });
  canvas.addEventListener('click',()=>player.jump());

  loop();
})();
